// ideal_descent.go — an ideal generated by polynomials over a subfield k
// meets the polynomials over k in the ideal they generate over k. A
// k-linear map of L into k, applied to the coefficients, carries a
// constant to a constant and the ideal over L into the ideal over k; one
// that fixes k fixes the polynomials over k, and carries F − β·G to
// F − π(β)·G for F and G over k.

package polynomial_algebra

import (
	"github.com/euc-ai/xugo/ext/on"
	. "github.com/euc-ai/xugo/library/authoring"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/field"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/field_extension"
	"github.com/euc-ai/xugo/library/proofs/algebra/group/comm_monoid"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/free_module"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/function_module"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/module"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/module_homomorphism"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/comm_ring"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_homomorphism"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_ideal"
	"github.com/euc-ai/xugo/library/proofs/sets/finite_set"
	"github.com/euc-ai/xugo/library/proofs/sets/set_basic"
	"github.com/euc-ai/xugo/library/proofs/sets/set_order"
	"github.com/euc-ai/xugo/library/registry"
)

// LinearCoefficientsMul — a k-linear map π of L into k, applied to the
// coefficients, commutes with multiplication by a polynomial over k: the
// coefficient of f · g at a monomial is a finite sum of f(m₁) · g(m − m₁)
// with g(m − m₁) in k, which π carries term by term to π(f(m₁)) · g(m − m₁).
var LinearCoefficientsMul = linearCoefficientsMulThm{family.Add(registry.ProofEntry{
	Name: "LinearCoefficientsMul",
	Key:  "prop_5d5f8e23d0166211",
	Reading: "g over k is load-bearing: π is only k-linear, so a factor of L " +
		"outside k does not pass through it. The sum at each monomial is finite " +
		"because a finitely supported monomial has finitely many monomials below it.",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀k:set(A). ∀π:(A → A). ∀S:set(D). ∀f g:((D → num) → A).",
		Hypotheses: []string{
			"subfield(L, k)",
			"«kLinear»(π)",
			"f ∈ polynomial_algebra(field_ring(L), S)",
			"g ∈ polynomial_algebra(«overK», S)",
		},
		Conclusion: "(λm:(D → num). π(polynomial_algebra_mul(field_ring(L), f, g, m))) = " +
			"polynomial_algebra_mul(«overK», λm:(D → num). π(f(m)), g)",
		Abbrev: Abbrev{
			{Name: "overK", Text: "restrict_ring(field_ring(L), k)"},
			{Name: "kLinear", Text: "module_homomorphism(«overK», " +
				"    regular_module(field_ring(L)), " +
				"    restrict_module(regular_module(field_ring(L)), k))"},
			{Name: "belowN", Text: "{m₁:(D → num) | ∀x:D. m₁(x) ≤ n(x)}"},
		},
	},
		func(
			a *Argument,
			L field.FieldFact[on.L],
			k *Expr[Set[A]],
			π *Arrow[A, A],
			S *Expr[Set[D]],
			f, g *Expr[Fun[Fun[D, Nat], A]],
			subK, linear, fOverL, gOverK Fact,
		) {
			fInL := a.Have(
				"the coefficients of f lie in L",
				"∀m:(D → num). f(m) ∈ L.carrier",
				By(fOverL, PolynomialAlgebraMember.At(a.TermAs[RingOps[A]]("field_ring(L)"), S, f)))
			gInK := a.Have(
				"the coefficients of g lie in k",
				"∀m:(D → num). g(m) ∈ k",
				By(gOverK, PolynomialAlgebraMember.At(a.TermAs[RingOps[A]]("«overK»"), S, g)))
			kInL := a.Have(
				"k lies in L",
				"k ⊆ L.carrier",
				By(field.SubfieldSubset.Read(subK)))
			commutes := comm_monoid.CommOn.Read(comm_ring.MulMonoidOn.Read(field.RingOn.Read(L)))
			passes := a.Have(
				"a factor of k passes through π: π(x · c) = π(x) · c",
				"∀x c:A. x ∈ L.carrier ∧ c ∈ k ⇒ π(x * c) = π(x) * c",
				Derive(func(b *Argument) {
					x := b.FixAs[A]("x")
					c := b.FixAs[A]("c")
					parts := b.Conjuncts(
						b.Assume(),
						"x lies in L",
						"c lies in k")
					b.Show(
						"π(x · c) = π(c · x) = c · π(x) = π(x) · c, π(x) lying in k",
						BySets(
							parts[1],
							parts[0],
							kInL,
							module_homomorphism.HomSmul.Read(linear).AsFact().At(c, x),
							module_homomorphism.HomIn.Read(linear).AsFact().At(x),
							commutes.AsFact().At(x, c),
							commutes.AsFact().At(π.Apply(x), c)))
				}))
			zero := a.Have(
				"π keeps zero",
				"π(L.zero) = L.zero",
				By(module_homomorphism.HomZero.Read(linear)))
			a.Show(
				"coefficient by coefficient",
				Funext(),
				Derive(func(b *Argument) {
					n := b.FixAs[Fun[D, Nat]]("n")
					b.Cases(b.TermAs[Bool]("finite_support(0, n)"))
					b.When(
						"at a finitely supported monomial the coefficient is a finite sum, which π carries term by term",
						func(c *Argument, finiteN Fact) {
							below := c.TermAs[Set[Fun[D, Nat]]]("«belowN»")
							add := c.TermAs[Op[A]]("L.add")
							zeroL := c.TermAs[A]("L.zero")
							termwise := c.Have(
								"π, additive and keeping zero, passes through the finite sum",
								"π(module_sum(L.add, L.zero, «belowN», λm₁:(D → num). f(m₁) * g(λx:D. n(x) - m₁(x)))) = "+
									"module_sum(L.add, L.zero, «belowN», λm₁:(D → num). π(f(m₁) * g(λx:D. n(x) - m₁(x))))",
								BySets(
									module_homomorphism.HomAdd.Read(linear),
									comm_ring.MulIn.Read(field.RingOn.Read(L)),
									finiteN,
									MonomialsBelowFinite.At(n),
									fInL,
									gInK,
									zero,
									kInL,
									module.ModuleSumMonoidHomomorphism.Read(comm_ring.AddMonoidOn.Read(field.RingOn.Read(L))).At(
										add,
										zeroL,
										π,
										below,
										c.TermAs[Fun[Fun[D, Nat], A]]("λm₁:(D → num). f(m₁) * g(λx:D. n(x) - m₁(x))"))))
							c.Show(
								"and the factor g(n − m₁) of k passes through π in each term",
								Simp(Fwd(PolynomialAlgebraMulDef)),
								By(
									passes,
									fInL,
									gInK,
									termwise,
									finiteN,
									module.ModuleSumCongruence.At(
										add,
										zeroL,
										below,
										c.TermAs[Fun[Fun[D, Nat], A]]("λm₁:(D → num). π(f(m₁) * g(λx:D. n(x) - m₁(x)))"),
										c.TermAs[Fun[Fun[D, Nat], A]]("λm₁:(D → num). π(f(m₁)) * g(λx:D. n(x) - m₁(x))"))))
						})
					b.Otherwise(
						"elsewhere both coefficients are zero",
						func(c *Argument, infinite Fact) {
							c.Show(
								"and π keeps zero",
								Simp(Fwd(PolynomialAlgebraMulDef)),
								By(infinite, zero))
						})
				}))
		}),
})}

// LinearCoefficientsConst — a k-linear map π of L into k, applied to the
// coefficients, carries the constant β to the constant π(β): the constant's
// coefficients are β at the monomial of the constants and L.zero elsewhere,
// and π keeps zero.
var LinearCoefficientsConst = linearCoefficientsConstThm{family.Add(registry.ProofEntry{
	Name: "LinearCoefficientsConst",
	Key:  "prop_c79fd4606d7eb75a",
	Build: family.Theorem(Statement{
		Binders:    "∀L:field_on(A). ∀k:set(A). ∀π:(A → A). ∀β:A.",
		Hypotheses: []string{"«kLinear»(π)"},
		Conclusion: "(λm:(D → num). π(polynomial_algebra_const(field_ring(L), β, m))) = " +
			"polynomial_algebra_const(«overK», π(β))",
		Abbrev: Abbrev{
			{Name: "overK", Text: "restrict_ring(field_ring(L), k)"},
			{Name: "kLinear", Text: "module_homomorphism(«overK», " +
				"    regular_module(field_ring(L)), " +
				"    restrict_module(regular_module(field_ring(L)), k))"},
		},
	},
		func(
			a *Argument,
			L field.FieldFact[on.L],
			k *Expr[Set[A]],
			π *Arrow[A, A],
			β *Expr[A],
			linear Fact,
		) {
			a.Do(Funext())
			a.FixAs[Fun[D, Nat]]("m")
			a.Do(Simp(Fwd(PolynomialAlgebraConstDef), Fwd(free_module.DeltaAtDef)))
			a.Cases(a.TermAs[Bool]("m = (λx:D. 0)"))
			a.When(
				"at the monomial of the constants both are π(β)",
				func(b *Argument, at Fact) {
					b.Show(
						"π(β) = π(β)",
						By(at))
				})
			a.Otherwise(
				"elsewhere both are zero, which π keeps",
				func(b *Argument, away Fact) {
					b.Show(
						"π(0) = 0",
						By(away, module_homomorphism.HomZero.Read(linear)))
				})
		}),
})}

// RetractionLinearFactor — a k-linear map π of L onto k fixing k, applied to
// the coefficients, carries F − β·G to F − π(β)·G for F and G over k: π
// fixes the coefficients of F, it is additive and keeps negatives, and it
// carries β·G to π(β)·G, the constant β to the constant π(β)
// (LinearCoefficientsConst) and a product by G over k to the product by G
// (LinearCoefficientsMul).
var RetractionLinearFactor = retractionLinearFactorThm{family.Add(registry.ProofEntry{
	Name: "RetractionLinearFactor",
	Key:  "prop_84f5d4d2fb9b5c6b",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀k:set(A). ∀π:(A → A). ∀S:set(D). ∀β:A. ∀F G:((D → num) → A).",
		Hypotheses: []string{
			"subfield(L, k)",
			"«kLinear»(π)",
			"∀c:A. c ∈ k ⇒ π(c) = c",
			"β ∈ L.carrier",
			"F ∈ polynomial_algebra(«overK», S)",
			"G ∈ polynomial_algebra(«overK», S)",
		},
		Conclusion: "(λm:(D → num). π(F(m) - «βG»(m))) = (λm:(D → num). F(m) - «πβG»(m))",
		Abbrev: Abbrev{
			{Name: "overK", Text: "restrict_ring(field_ring(L), k)"},
			{Name: "kLinear", Text: "module_homomorphism(«overK», " +
				"    regular_module(field_ring(L)), " +
				"    restrict_module(regular_module(field_ring(L)), k))"},
			{Name: "βG", Text: "polynomial_algebra_mul(field_ring(L), " +
				"    polynomial_algebra_const(field_ring(L), β), " +
				"    G)"},
			{Name: "πβG", Text: "polynomial_algebra_mul(«overK», polynomial_algebra_const(«overK», π(β)), G)"},
		},
	},
		func(
			a *Argument,
			L field.FieldFact[on.L],
			k *Expr[Set[A]],
			π *Arrow[A, A],
			S *Expr[Set[D]],
			β *Expr[A],
			F, G *Arrow[Fun[D, Nat], A],
			subK, linear, fixesK, betaIn, fOverK, gOverK Fact,
		) {
			type poly = Fun[Fun[D, Nat], A]
			fieldRing := a.TermAs[RingOps[A]]("field_ring(L)")
			ringL := field.RingOn.Read(L)
			kInL := a.Have(
				"k lies in L",
				"k ⊆ L.carrier",
				By(field.SubfieldSubset.Read(subK)))
			overLOn := a.Have(
				"the polynomials over L are a commutative ring",
				"comm_ring_on(polynomial_algebra_ring(field_ring(L), S))",
				By(ringL, PolynomialAlgebraCommRingOn.At(fieldRing, S)))
			constants := a.Have(
				"the constants over L are a ring map",
				"ring_homomorphism(field_ring(L), "+
					"    polynomial_algebra_ring(field_ring(L), S), "+
					"    polynomial_algebra_const(field_ring(L)))",
				By(ringL, PolynomialAlgebraConstHom.At(fieldRing, S)))
			constantBeta := a.TermAs[poly]("polynomial_algebra_const(field_ring(L), β)")
			constantBetaIn := a.Have(
				"the constant β is a polynomial over L",
				"polynomial_algebra_const(field_ring(L), β) ∈ polynomial_algebra(field_ring(L), S)",
				By(betaIn, ring_homomorphism.MapIn.Read(constants).AsFact().At(β)))
			gOverL := a.Have(
				"G, over k, is a polynomial over L",
				"G ∈ polynomial_algebra(field_ring(L), S)",
				BySets(gOverK, kInL, PolynomialAlgebraOverMono.At(fieldRing, k, S)))
			piProduct := a.Have(
				"π carries β·G to π(β)·G, G being over k",
				"(λm:(D → num). π(«βG»(m))) = «πβG»",
				By(
					subK,
					linear,
					constantBetaIn,
					gOverK,
					LinearCoefficientsMul.Read(L).At(k, π, S, constantBeta, G),
					LinearCoefficientsConst.Read(L).At(k, π, β)))
			productL := a.Have(
				"β·G is a polynomial over L",
				"«βG» ∈ polynomial_algebra(field_ring(L), S)",
				By(constantBetaIn, gOverL, comm_ring.MulIn.Read(overLOn).AsFact().At(constantBeta, G)))
			coefficientsK := a.Have(
				"a polynomial over k has its coefficients in k",
				"∀P:((D → num) → A). ∀m:(D → num). P ∈ polynomial_algebra(«overK», S) ⇒ P(m) ∈ k",
				By(At(PolynomialAlgebraMember, a.Term("«overK»"), S)))
			coefficientsL := a.Have(
				"a polynomial over L has its coefficients in L",
				"∀P:((D → num) → A). ∀m:(D → num). P ∈ polynomial_algebra(field_ring(L), S) ⇒ P(m) ∈ L.carrier",
				By(At(PolynomialAlgebraMember, fieldRing, S)))
			productBetaG := a.TermAs[poly]("«βG»")
			a.Show(
				"coefficient by coefficient",
				Funext(),
				Derive(func(b *Argument) {
					m := b.FixAs[Fun[D, Nat]]("m")
					fm := b.TermAs[A]("F(m)")
					βGm := b.TermAs[A]("«βG»(m)")
					members := b.Have(
						"F(m), (β·G)(m) and (π(β)·G)(m) lie in L",
						"F(m) ∈ L.carrier ∧ «βG»(m) ∈ L.carrier ∧ «πβG»(m) ∈ L.carrier",
						By(
							fOverK,
							productL,
							coefficientsK.At(F, m),
							coefficientsL.At(productBetaG, m),
							kInL,
							set_basic.SubsetDef,
							piProduct,
							module_homomorphism.HomIn.Read(linear).AsFact().At(βGm)))
					split := b.Have(
						"F(m) − (β·G)(m) is F(m) + −(β·G)(m)",
						"F(m) - «βG»(m) = F(m) + -«βG»(m)",
						ByArith(L, members))
					rejoin := b.Have(
						"F(m) + −(π(β)·G)(m) is F(m) − (π(β)·G)(m)",
						"F(m) + -«πβG»(m) = F(m) - «πβG»(m)",
						ByArith(L, members))
					fixed := b.Have(
						"π fixes F(m), a member of k",
						"π(F(m)) = F(m)",
						By(fixesK.At(fm), coefficientsK.At(F, m), fOverK))
					productAt := b.Have(
						"π carries (β·G)(m) to (π(β)·G)(m)",
						"π(«βG»(m)) = «πβG»(m)",
						By(piProduct))
					additive := b.Have(
						"π is additive and keeps negatives",
						"π(F(m) + -«βG»(m)) = π(F(m)) + -π(«βG»(m))",
						By(
							module_homomorphism.HomAdd.Read(linear).AsFact().At(fm, b.TermAs[A]("-«βG»(m)")),
							At(
								module_homomorphism.HomNeg,
								b.Term("«overK»"),
								b.Term("regular_module(field_ring(L))"),
								b.Term("restrict_module(regular_module(field_ring(L)), k)"),
								π,
								βGm),
							linear,
							members,
							comm_ring.NegIn.Read(ringL).AsFact().At(βGm)))
					b.Show(
						"so π(F(m) − (β·G)(m)) = F(m) − (π(β)·G)(m)",
						split.Rw(),
						By(additive, fixed, productAt, rejoin))
				}))
		}),
})}

// IdealLinearDescent — a k-linear map π of L into a subfield k, applied to
// the coefficients, carries the ideal that polynomials E over k generate
// over L into the ideal E generates over k: P lies in the ideal over L of a
// finite part of E, and by induction on that part π carries each ideal
// combination over L to one over k, one generator at a time — b · x + w
// goes to π(b) · x + π(w).
var IdealLinearDescent = idealLinearDescentThm{family.Add(registry.ProofEntry{
	Name: "IdealLinearDescent",
	Key:  "prop_e9726d375d78a258",
	Reading: "π need not fix k: any k-linear map of L into k will do, the coordinate functionals " +
		"of a k-basis of L among them. E over k is load-bearing: π passes only over a factor of k.",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). " +
			"∀k:set(A). " +
			"∀π:(A → A). " +
			"∀S:set(D). " +
			"∀E:set((D → num) → A). " +
			"∀P:((D → num) → A).",
		Hypotheses: []string{
			"subfield(L, k)",
			"«kLinear»(π)",
			"E ⊆ «polysK»",
			"P ∈ ideal_span(«ringL», E)",
		},
		Conclusion: "(λm:(D → num). π(P(m))) ∈ «idealK»",
		Abbrev: Abbrev{
			{Name: "overK", Text: "restrict_ring(field_ring(L), k)"},
			{Name: "polysL", Text: "polynomial_algebra(field_ring(L), S)"},
			{Name: "polysK", Text: "polynomial_algebra(«overK», S)"},
			{Name: "ringL", Text: "polynomial_algebra_ring(field_ring(L), S)"},
			{Name: "ringK", Text: "polynomial_algebra_ring(«overK», S)"},
			{Name: "kLinear", Text: "module_homomorphism(«overK», " +
				"    regular_module(field_ring(L)), " +
				"    restrict_module(regular_module(field_ring(L)), k))"},
			{Name: "idealK", Text: "ideal_span(«ringK», E)"},
		},
	},
		func(
			a *Argument,
			L field.FieldFact[on.L],
			k *Expr[Set[A]],
			π *Arrow[A, A],
			S *Expr[Set[D]],
			E *Expr[Set[Fun[Fun[D, Nat], A]]],
			P *Arrow[Fun[D, Nat], A],
			subK, linear, eOverK, pInIdealL Fact,
		) {
			type poly = Fun[Fun[D, Nat], A]
			fieldRing := a.TermAs[RingOps[A]]("field_ring(L)")
			ringL := a.TermAs[RingOps[poly]]("«ringL»")
			ringK := a.TermAs[RingOps[poly]]("«ringK»")
			idealK := a.TermAs[Set[poly]]("«idealK»")
			ringLOn := a.Have(
				"the polynomials over L are a commutative ring",
				"comm_ring_on(«ringL»)",
				By(field.RingOn.Read(L), PolynomialAlgebraCommRingOn.At(fieldRing, S)))
			overKOn := a.Have(
				"k, a subfield of L, is a commutative ring under L's operations",
				"comm_ring_on(«overK»)",
				By(subK, field.SubfieldCommRing.Read(L).At(k)))
			ringKOn := a.Have(
				"and so are the polynomials over k",
				"comm_ring_on(«ringK»)",
				By(overKOn, PolynomialAlgebraCommRingOn.At(a.TermAs[RingOps[A]]("«overK»"), S)))
			eOverL := a.Have(
				"E consists of polynomials over k, so of polynomials over L",
				"E ⊆ «polysL»",
				BySets(eOverK, field.SubfieldSubset.Read(subK), PolynomialAlgebraOverMono.At(fieldRing, k, S)))
			zero := a.Have(
				"π keeps zero",
				"π(L.zero) = L.zero",
				By(module_homomorphism.HomZero.Read(linear)))
			coefficients := a.Have(
				"a polynomial over L has its coefficients in L",
				"∀Q:((D → num) → A). ∀m:(D → num). Q ∈ «polysL» ⇒ Q(m) ∈ L.carrier",
				By(At(PolynomialAlgebraMember, fieldRing, S)))
			descends := a.Have(
				"π applied to the coefficients of a polynomial over L gives a polynomial over k",
				"∀Q:((D → num) → A). Q ∈ «polysL» ⇒ (λm:(D → num). π(Q(m))) ∈ «polysK»",
				Simp(Fwd(PolynomialAlgebraMember)),
				Derive(func(b *Argument) {
					b.FixAs[poly]("Q")
					parts := b.Conjuncts(
						b.Assume(),
						"Q is nonzero at finitely many monomials",
						"every monomial where Q is nonzero is a monomial of S",
						"every coefficient of Q lies in L")
					imageSupport := b.TermAs[Set[Fun[D, Nat]]]("fun_support(L.zero, λm:(D → num). π(Q(m)))")
					support := b.TermAs[Set[Fun[D, Nat]]]("fun_support(L.zero, Q)")
					within := b.Have(
						"π keeps zero, so π ∘ Q is nonzero only where Q is",
						"fun_support(L.zero, λm:(D → num). π(Q(m))) ⊆ fun_support(L.zero, Q)",
						BySets(zero))
					b.Show(
						"so π ∘ Q is nonzero at finitely many monomials, all "+
							"of them monomials of S, and its coefficients lie in k",
						By(
							within,
							parts[0],
							parts[1],
							parts[2],
							module_homomorphism.HomIn.Read(linear),
							finite_set.FiniteSubset.At(imageSupport, support),
							set_order.SubsetTrans.At(imageSupport, support, b.TermAs[Set[Fun[D, Nat]]]("monomials(S)"))))
				}))
			T, finitePart := a.ObtainAs[Set[poly]](
				"P lies in the ideal over L of a finite part T of E",
				"∃T:set((D → num) → A). finite(T) ∧ T ⊆ E ∧ P ∈ ideal_span(«ringL», T)",
				By(pInIdealL, eOverL, ring_ideal.SpanFinite.Read(ringLOn).At(E, P)))
			descent := a.Have(
				"π carries the ideal over L of a finite part of E into the ideal of E over k",
				Statement{
					Binders:    "∀U:set((D → num) → A).",
					Hypotheses: []string{"finite(U)", "U ⊆ E"},
					Conclusion: "∀u:((D → num) → A). u ∈ ideal_span(«ringL», U) ⇒ (λm:(D → num). π(u(m))) ∈ «idealK»",
				},
				Derive(func(c *Argument) {
					U := c.FixAs[Set[poly]]("U")
					partOfE := c.Assume()
					c.Show(
						"by induction on the finite part",
						ByInduction(
							finite_set.FiniteInductFreshOn.At(
								c.TermAs[Set[Set[poly]]](
									"λt:set((D → num) → A). ∀u:((D → num) → A). "+
										"    u ∈ ideal_span(«ringL», t) ⇒ (λm:(D → num). π(u(m))) ∈ «idealK»"),
								c.TermAs[Set[poly]]("λy:((D → num) → A). y ∈ E"),
								U),
							partOfE,
							set_basic.SubsetDef,
							Case(
								"the ideal of nothing is zero alone, and π carries zero to zero",
								Derive(func(d *Argument) {
									d.FixAs[poly]("u")
									uInIdeal := d.Assume()
									zeroL := d.TermAs[Set[poly]]("{«ringL».zero}")
									idealOfNothing := d.Have(
										"the ideal over L of nothing is zero alone",
										"ideal_span(«ringL», ∅) ⊆ {«ringL».zero}",
										By(
											ring_ideal.SpanLeast.At(ringL, d.TermAs[Set[poly]]("∅"), zeroL),
											ring_ideal.ZeroIdeal.Read(ringLOn),
											set_order.EmptySubset.At(zeroL)))
									uZero := d.Have(
										"so u is zero",
										"u = «ringL».zero",
										BySets(uInIdeal, idealOfNothing))
									image := d.Have(
										"π carries the zero polynomial over L to the zero polynomial over k",
										"(λm:(D → num). π(u(m))) = «ringK».zero",
										uZero.Rw(),
										Funext(),
										Simp(Fwd(PolynomialAlgebraRingDef), Fwd(function_module.FunZeroDef)),
										By(zero))
									d.Show(
										"which lies in every ideal",
										By(image, eOverK, ring_ideal.IdealZero, ring_ideal.SpanIdeal.Read(ringKOn).At(E)))
								})),
							Case(
								"an ideal combination over insert(x, t) is b · x + "+
									"w with w over t, and π carries it to π(b) · x + π(w)",
								Derive(func(d *Argument) {
									x := d.FixAs[poly]("x")
									t := d.FixAs[Set[poly]]("t")
									stepParts := d.Conjuncts(
										d.Assume(),
										"the induction hypothesis at t",
										"x is new to t",
										"t is finite",
										"x lies in E",
										"t lies in E")
									ih, xInE, tInE := stepParts[0], stepParts[3], stepParts[4]
									d.FixAs[poly]("u")
									uInIdeal := d.Assume()
									b, w, combination := d.Obtain2As[poly, poly](
										"u is b · x + w with b over L and w in the ideal of t",
										"∃b w:((D → num) → A). "+
											"    b ∈ «polysL» ∧ "+
											"    w ∈ ideal_span(«ringL», t) ∧ "+
											"    u = fun_add(polynomial_algebra_mul(field_ring(L), b, x), w)",
										BySets(tInE, uInIdeal, xInE, eOverL, ring_ideal.SpanInsert.Read(ringLOn).AsFact().At(t, x)))
									combinationParts := d.Conjuncts(
										combination,
										"b is a polynomial over L",
										"w lies in the ideal of t",
										"u is b · x + w")
									bOverL, wInIdeal, uIs := combinationParts[0], combinationParts[1], combinationParts[2]
									xOverK := d.Have(
										"x is a polynomial over k",
										"x ∈ «polysK»",
										BySets(xInE, eOverK))
									summands := d.Have(
										"b · x and w are polynomials over L",
										"polynomial_algebra_mul(field_ring(L), b, x) ∈ «polysL» ∧ w ∈ «polysL»",
										BySets(
											bOverL,
											wInIdeal,
											xInE,
											eOverL,
											tInE,
											comm_ring.MulIn.Read(ringLOn).AsFact().At(b, x),
											ring_ideal.SpanIdeal.Read(ringLOn).At(t),
											ring_ideal.IdealSubset))
									bx := d.TermAs[poly]("polynomial_algebra_mul(field_ring(L), b, x)")
									image := d.Have(
										"π carries b · x + w to π(b) · x + π(w)",
										"(λm:(D → num). π(u(m))) = "+
											"fun_add(polynomial_algebra_mul(«overK», λm:(D → num). π(b(m)), x), λm:(D → num). π(w(m)))",
										uIs.Rw(),
										Funext(),
										Derive(func(e *Argument) {
											n := e.FixAs[Fun[D, Nat]]("n")
											e.Show(
												"π is additive, and passes over the factor x over k",
												Simp(Fwd(function_module.FunAddDef)),
												By(
													coefficients.At(bx, n),
													coefficients.At(w, n),
													summands,
													subK,
													bOverL,
													xOverK,
													module_homomorphism.HomAdd.Read(linear).AsFact().At(
														e.TermAs[A]("polynomial_algebra_mul(field_ring(L), b, x, n)"),
														e.TermAs[A]("w(n)")),
													LinearCoefficientsMul.Read(L).At(k, π, S, b, x)))
										}))
									xInIdealK := d.Have(
										"x lies in the ideal of E over k",
										"x ∈ «idealK»",
										BySets(xInE, ring_ideal.SpanContains.At(ringK, E)))
									πb := d.TermAs[poly]("λm:(D → num). π(b(m))")
									product := d.TermAs[poly]("polynomial_algebra_mul(«overK», λm:(D → num). π(b(m)), x)")
									d.Show(
										"π(b) is over k and π(w) lies in the ideal by the "+
											"induction hypothesis, so π(b) · x + π(w) lies in it",
										By(
											image,
											descends.At(b),
											bOverL,
											ih.At(w),
											wInIdeal,
											xInIdealK,
											eOverK,
											ring_ideal.SpanIdeal.Read(ringKOn).At(E),
											ring_ideal.IdealMul.At(ringK, idealK, πb, x),
											ring_ideal.IdealAdd.At(ringK, idealK, product, d.TermAs[poly]("λm:(D → num). π(w(m))"))))
								}))))
				}))
			a.Show(
				"so π carries P into the ideal of E over k",
				By(descent.At(T, P), finitePart))
		}),
})}

// IdealDescent — for polynomials E over a subfield k of L, a polynomial over
// k in the ideal E generates over L lies in the ideal E generates over k: a
// k-linear map π of L onto k fixing k, applied to the coefficients, carries
// P into the ideal over k, and it fixes P, whose coefficients lie in k.
var IdealDescent = idealDescentThm{family.Add(registry.ProofEntry{
	Name: "IdealDescent",
	Reading: "k a subfield is load-bearing, L then having a k-basis through 1: over " +
		"the subring ℤ of ℚ with E = {2}, 1 lies in the ideal over ℚ but not over ℤ.",
	Key: "prop_11713847c542695e",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀k:set(A). ∀S:set(D). ∀E:set((D → num) → A). ∀P:((D → num) → A).",
		Hypotheses: []string{
			"subfield(L, k)",
			"E ⊆ «polysK»",
			"P ∈ «polysK»",
			"P ∈ ideal_span(«ringL», E)",
		},
		Conclusion: "P ∈ «idealK»",
		Abbrev: Abbrev{
			{Name: "overK", Text: "restrict_ring(field_ring(L), k)"},
			{Name: "polysK", Text: "polynomial_algebra(«overK», S)"},
			{Name: "ringL", Text: "polynomial_algebra_ring(field_ring(L), S)"},
			{Name: "ringK", Text: "polynomial_algebra_ring(«overK», S)"},
			{Name: "kLinear", Text: "module_homomorphism(«overK», " +
				"    regular_module(field_ring(L)), " +
				"    restrict_module(regular_module(field_ring(L)), k))"},
			{Name: "idealK", Text: "ideal_span(«ringK», E)"},
		},
	},
		func(
			a *Argument,
			L field.FieldFact[on.L],
			k *Expr[Set[A]],
			S *Expr[Set[D]],
			E *Expr[Set[Fun[Fun[D, Nat], A]]],
			P *Arrow[Fun[D, Nat], A],
			subK, eOverK, pOverK, pInIdealL Fact,
		) {
			π, retraction := a.ObtainAs[Fun[A, A]](
				"a k-linear map π of L onto k fixing k",
				"∃π:(A → A). «kLinear»(π) ∧ (∀c:A. c ∈ k ⇒ π(c) = c)",
				By(subK, field_extension.SubfieldRetraction.Read(L).At(k)))
			retractionParts := a.Conjuncts(
				retraction,
				"π is k-linear",
				"π fixes k")
			linear, fixesK := retractionParts[0], retractionParts[1]
			fixesP := a.Have(
				"π fixes P, whose coefficients lie in k",
				"(λm:(D → num). π(P(m))) = P",
				Funext(),
				Derive(func(b *Argument) {
					m := b.FixAs[Fun[D, Nat]]("m")
					b.Show(
						"each coefficient of P lies in k",
						By(
							fixesK.At(P.Apply(m)),
							pOverK,
							PolynomialAlgebraMember.At(b.TermAs[RingOps[A]]("«overK»"), S, P)))
				}))
			a.Show(
				"so P, the image of itself under π, lies in the ideal of E over k",
				By(subK, linear, eOverK, pInIdealL, fixesP, IdealLinearDescent.Read(L).At(k, π, S, E, P)))
		}),
})}

// IdealExtension — for polynomials E over a subfield k of L, the ideal E
// generates over k lies in the ideal it generates over L: the polynomials
// over k lying in the ideal over L are an ideal of the polynomials over k,
// since the two rings multiply alike, and they hold E.
var IdealExtension = idealExtensionThm{family.Add(registry.ProofEntry{
	Name: "IdealExtension",
	Key:  "prop_ef79b476658b9513",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀k:set(A). ∀S:set(D). ∀E:set((D → num) → A).",
		Hypotheses: []string{
			"subfield(L, k)",
			"E ⊆ «polysK»",
		},
		Conclusion: "«idealK» ⊆ ideal_span(«ringL», E)",
		Abbrev: Abbrev{
			{Name: "overK", Text: "restrict_ring(field_ring(L), k)"},
			{Name: "polysK", Text: "polynomial_algebra(«overK», S)"},
			{Name: "ringL", Text: "polynomial_algebra_ring(field_ring(L), S)"},
			{Name: "ringK", Text: "polynomial_algebra_ring(«overK», S)"},
			{Name: "idealK", Text: "ideal_span(«ringK», E)"},
		},
	},
		func(
			a *Argument,
			L field.FieldFact[on.L],
			k *Expr[Set[A]],
			S *Expr[Set[D]],
			E *Expr[Set[Fun[Fun[D, Nat], A]]],
			subK, eOverK Fact,
		) {
			type poly = Fun[Fun[D, Nat], A]
			fieldRing := a.TermAs[RingOps[A]]("field_ring(L)")
			ringL := a.TermAs[RingOps[poly]]("«ringL»")
			ringK := a.TermAs[RingOps[poly]]("«ringK»")
			ringLOn := a.Have(
				"the polynomials over L are a commutative ring",
				"comm_ring_on(«ringL»)",
				By(field.RingOn.Read(L), PolynomialAlgebraCommRingOn))
			overKOn := a.Have(
				"k, a subfield of L, is a commutative ring under L's operations",
				"comm_ring_on(«overK»)",
				By(subK, field.SubfieldCommRing.Read(L).At(k)))
			ringKOn := a.Have(
				"and so are the polynomials over k",
				"comm_ring_on(«ringK»)",
				By(overKOn, PolynomialAlgebraCommRingOn))
			polysKInL := a.Have(
				"a polynomial over k is one over L",
				"«polysK» ⊆ polynomial_algebra(field_ring(L), S)",
				By(field.SubfieldSubset.Read(subK), PolynomialAlgebraOverMono.At(fieldRing, k, S)))
			idealL := a.Have(
				"E generates an ideal of the polynomials over L",
				"ring_ideal(«ringL», ideal_span(«ringL», E))",
				BySets(eOverK, polysKInL, ring_ideal.SpanIdeal.Read(ringLOn).At(E)))
			trace := a.Have(
				"so the polynomials over k in the ideal over L are an ideal of the polynomials over k",
				"ring_ideal(«ringK», ideal_span(«ringL», E) ∩ «polysK»)",
				Simp(Fwd(ring_ideal.RingIdealDef)),
				SplitConj(
					Case(
						"it holds zero and is closed under sums",
						BySets(
							idealL,
							ring_ideal.IdealZero,
							ring_ideal.IdealAdd,
							comm_ring.ZeroIn.Read(ringKOn),
							comm_ring.AddIn.Read(ringKOn))),
					Case(
						"and under multiplication by a polynomial over k, one over L, which multiplies as it does over L",
						BySets(
							At(PolynomialAlgebraMulRestrict, fieldRing, k),
							idealL,
							polysKInL,
							ring_ideal.IdealMul,
							comm_ring.MulIn.Read(ringKOn)))))
			a.Show(
				"it holds E, so it holds the ideal E generates over k",
				BySets(
					trace,
					eOverK,
					ring_ideal.SpanLeast.At(ringK, E, a.TermAs[Set[poly]]("ideal_span(«ringL», E) ∩ «polysK»")),
					ring_ideal.SpanContains.At(ringL, E)))
		}),
})}
